const INPUT_LIMITS={name:30,oneLineDescription:50,technologyOther:20,repName:5,repBirth:4,stage:30,headOffice:80,factory:80,lab:80,headOfficeDetail:30,factoryDetail:30,labDetail:30,team:500};
function formatRegistration(value,corporate=false){const d=String(value||'').replace(/\D/g,'').slice(0,corporate?13:10);return corporate?[d.slice(0,6),d.slice(6)].filter(Boolean).join('-'):[d.slice(0,3),d.slice(3,5),d.slice(5)].filter(Boolean).join('-');}
function addressFields(c,name,label,optional=false){return `<div class="address-field full"><div class="address-line">${profileField(label+' 주소',name,c[name],{optional,length:80,placeholder:'주소 검색 또는 직접 입력'})}<button type="button" class="btn" onclick="searchAddress('${name}')">주소 검색</button></div>${profileField(label+' 상세주소',name+'Detail',c[name+'Detail']||'',{optional:true,length:30,placeholder:'동·층·호수 등, 최대 30자'})}</div>`;}
let postcodeLoading;
async function searchAddress(name){const dialog=document.createElement('dialog');dialog.className='address-dialog';dialog.innerHTML='<div class="topline"><b>사업장 주소 검색</b><button type="button" class="btn">닫기</button></div><p role="status">주소 검색을 불러오고 있습니다…</p><div class="postcode-host"></div>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();try{if(!window.kakao?.Postcode&&!window.daum?.Postcode){if(!postcodeLoading)postcodeLoading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://t1.kakaocdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js';s.onload=resolve;s.onerror=()=>{postcodeLoading=null;reject(Error('주소 검색을 불러오지 못했습니다. 주소를 직접 입력해 주세요.'));};document.head.append(s);});await postcodeLoading;}if(!dialog.isConnected)return;dialog.querySelector('p').hidden=true;const Postcode=window.kakao?.Postcode||window.daum?.Postcode;new Postcode({width:'100%',height:'100%',oncomplete:data=>{const form=$('#companyform');form.elements[name].value=data.userSelectedType==='R'?data.roadAddress:data.jibunAddress;form.elements[name].dispatchEvent(new Event('input',{bubbles:true}));dialog.close();form.elements[name+'Detail'].focus();}}).embed(dialog.querySelector('.postcode-host'));}catch(e){if(dialog.isConnected)dialog.querySelector('p').textContent=e.message;}}
function achievementRows(c){if(Array.isArray(c.achievementEntries))return c.achievementEntries;return String(c.achievements||'').split('\n').filter(Boolean).map(line=>{const m=line.match(/^(\d{4})\s*[·.\-:]?\s*(.*)$/);return {year:m?m[1]:'',text:m?m[2]:line};});}
function achievementRow(entry={year:'',text:''}){const now=new Date().getFullYear();return `<div class="achievement-row"><label class="field">연도<select name="achievementYear" required aria-label="성과 연도"><option value="">연도 선택</option>${Array.from({length:now-1949},(_,i)=>now-i).map(y=>`<option value="${y}" ${String(y)===String(entry.year)?'selected':''}>${y}년</option>`).join('')}</select></label><label class="field">주요 실적·성과<input name="achievementText" required maxlength="120" value="${esc(entry.text)}" placeholder="예: 핵심 기술 특허 등록 (최대 120자)"></label><button class="btn" type="button" onclick="this.closest('.achievement-row').remove()">삭제</button></div>`;}
function achievementEditor(c){const rows=achievementRows(c);return `<div class="full"><h3>주요 실적·성과</h3><p class="smallnote">연도와 성과를 입력해 주세요. 항목당 최대 120자, 최대 10개.</p><div id="achievement-rows">${rows.map(achievementRow).join('')}</div><button class="btn" type="button" onclick="addAchievement()">＋ 성과 추가</button></div>`;}
function addAchievement(){if($('#achievement-rows').children.length>=10)return toast('성과는 최대 10개까지 입력할 수 있습니다.');$('#achievement-rows').insertAdjacentHTML('beforeend',achievementRow());}
function bindEnhancedInputs(form){form.querySelectorAll('input[type="text"],input:not([type]),textarea').forEach(input=>{const limit=INPUT_LIMITS[input.name];if(!limit||input.classList.contains('picker-value'))return;input.maxLength=limit;const help=document.createElement('small');help.className='input-counter';input.after(help);const update=()=>{help.textContent=input.value.length+' / '+limit+'자';input.setCustomValidity(input.value.length>limit?'최대 '+limit+'자 이내로 줄여주세요.':'');};input.addEventListener('input',update);update();});for(const name of ['businessNo','corporateNo']){const input=form.elements[name];if(!input)continue;input.inputMode='numeric';input.value=formatRegistration(input.value,name==='corporateNo');input.addEventListener('input',()=>{const digitsBefore=input.value.slice(0,input.selectionStart).replace(/\D/g,'').length;input.value=formatRegistration(input.value,name==='corporateNo');let pos=0,count=0;while(pos<input.value.length&&count<digitsBefore){if(/\d/.test(input.value[pos]))count++;pos++;}input.setSelectionRange(pos,pos);});}}
function validateEnhancedData(data,fd){for(const [key,max] of Object.entries(INPUT_LIMITS)){if(typeof data[key]==='string'&&data[key].trim().length>max)throw Error('입력 글자 수를 확인해 주세요. '+({name:'기업명',oneLineDescription:'한 줄 소개',technologyOther:'기타 기술',repName:'대표자명',team:'핵심팀 경력'}[key]||'입력 항목')+' 최대 '+max+'자');}if(!String(data.name||'').trim())throw Error('기업명을 입력해 주세요.');data.name=data.name.trim();data.businessNo=formatRegistration(data.businessNo);data.corporateNo=formatRegistration(data.corporateNo,true);const texts=fd.getAll('achievementText'),years=fd.getAll('achievementYear');if(texts.length>10)throw Error('성과는 최대 10개입니다.');data.achievementEntries=texts.map((text,i)=>({year:String(years[i]||''),text:String(text).trim()}));if(data.achievementEntries.some(e=>!e.text||e.text.length>120||!/^\d{4}$/.test(e.year)||Number(e.year)<1950||Number(e.year)>new Date().getFullYear()))throw Error('성과 연도와 120자 이내의 내용을 확인해 주세요.');data.achievements=data.achievementEntries.map(e=>e.year+' · '+e.text).join('\n');delete data.achievementText;delete data.achievementYear;data.employmentBasis='cumulative';return data;}
function hasPdf(c){return !!c.irKey||typeof c.irData==='string'&&/^data:[^,]*;base64,JVBERi0/.test(c.irData);}
function pdfName(c){return String(c.name||'기업').replace(/[\\/:*?"<>|]/g,'_')+'_IR.pdf';}
async function validatePdf(file){if(file.size>30*1024*1024||!/\.pdf$/i.test(file.name))throw Error('IR은 30MB 이하의 PDF 파일만 지원합니다.');const signature=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(signature!=='%PDF-')throw Error('올바른 PDF 파일을 선택해 주세요.');}

function numericValue(value){return String(value??'').replace(/,/g,'')}
function groupedNumber(value){const raw=numericValue(value);if(!raw)return '';const [whole,decimal]=raw.split('.');return whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(decimal!==undefined?'.'+decimal:'')}
function bindGroupedNumbers(form){form.querySelectorAll('input[type="number"]').forEach(input=>{const integer=input.step==='1';input.type='text';input.inputMode=integer?'numeric':'decimal';input.dataset.numeric='true';input.dataset.integer=String(integer);let last=groupedNumber(input.value);input.value=last;const valid=value=>integer?/^\d*$/.test(value):/^(?:\d+(?:\.\d{0,2})?)?$/.test(value);input.addEventListener('input',()=>{const raw=numericValue(input.value);if(!valid(raw)){input.value=last;return;}const caret=input.selectionStart,before=input.value.slice(0,caret).replace(/,/g,'').length;last=groupedNumber(raw);input.value=last;input.setCustomValidity('');let pos=0,n=0;while(pos<input.value.length&&n<before){if(input.value[pos]!==',')n++;pos++;}input.setSelectionRange(pos,pos);});input.addEventListener('blur',()=>{if(numericValue(input.value).endsWith('.')){last=groupedNumber(numericValue(input.value).slice(0,-1));input.value=last;}});});}
function irDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('jb-port-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('pdfs');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('브라우저 파일 저장소를 열지 못했습니다.'))})}
async function storePdf(file){const db=await irDatabase(),key=crypto.randomUUID();try{await new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('IR 파일을 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.'));tx.onabort=tx.onerror});return key}finally{db.close()}}
async function readPdf(c){if(c.irKey){const db=await irDatabase();try{const blob=await new Promise((resolve,reject)=>{const req=db.transaction('pdfs').objectStore('pdfs').get(c.irKey);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('IR 자료를 읽지 못했습니다.'))});if(!blob)throw Error('저장된 IR 자료가 없습니다. 다시 업로드해 주세요.');return new Uint8Array(await blob.arrayBuffer())}finally{db.close()}}return irBytes(c)}
function validateCompanyForm(form){
 const errors=[];
 form.querySelectorAll('input').forEach(input=>{
  if(input.disabled)return;
  if(input.required)input.setCustomValidity(input.value.trim()?'':'필수 항목을 입력해 주세요.');
  if(input.maxLength>0&&input.value.length>input.maxLength)input.setCustomValidity('최대 '+input.maxLength+'자 이내로 입력해 주세요.');
  const invalid=!input.checkValidity();
  input.setAttribute('aria-invalid',String(invalid));
  const picker=input.closest('.picker-field');
  if(picker)picker.querySelector('summary').setAttribute('aria-invalid',String(invalid));
  if(invalid){const label=input.getAttribute('aria-label')||input.closest('.field')?.firstChild?.textContent?.trim()||'입력 항목';errors.push({input,picker,label});}
 });
 const box=form.querySelector('#form-errors');box.hidden=!errors.length;
 box.textContent=errors.length?'필수 항목 또는 입력 형식을 확인해 주세요: '+[...new Set(errors.map(e=>e.label))].join(', '):'';
 if(errors.length){const first=errors[0];(first.picker?.querySelector('summary')||first.input).focus();return false;}
 return true;
}
function companyWorkplaces(c){if(Array.isArray(c.workplaces)&&c.workplaces.length)return c.workplaces;return [['본점','headOffice'],['공장','factory'],['연구소','lab']].filter(([t,k])=>t==='본점'||c[k]).map(([type,k])=>({type,address:c[k]||(type==='본점'?c.city:'')||'',detail:c[k+'Detail']||''}));}
let workplaceIndex=0;
function workplaceRow(w){const id='workplace_'+workplaceIndex++;return '<div class="workplace-row"><div class="workplace-top"><fieldset class="workplace-types"><legend>사업장 종류 <span class="required-mark">필수</span></legend><div>'+['본점','공장','연구소'].map(t=>'<label><input type="radio" name="'+id+'_type" value="'+t+'" '+(w.type===t?'checked':'')+'><span>'+t+'</span></label>').join('')+'</div></fieldset><button type="button" class="btn remove-workplace" aria-label="이 사업장 삭제">삭제</button></div>'+addressFields({[id]:w.address,[id+'Detail']:w.detail},id,'사업장')+'</div>';}
function bindWorkplaces(form){const host=form.querySelector('#workplaces'),add=form.querySelector('#add-workplace');function sync(){const rows=[...host.querySelectorAll('.workplace-row')],head=host.querySelector('input[value="본점"]:checked');host.querySelectorAll('input[value="본점"]').forEach(r=>r.disabled=!!head&&r!==head);add.disabled=rows.length>=5;add.textContent=rows.length>=5?'사업장 최대 5곳 등록됨':'＋ 사업장 추가 ('+rows.length+'/5)';}add.onclick=()=>{if(host.children.length>=5)return;host.insertAdjacentHTML('beforeend',workplaceRow({type:'공장',address:'',detail:''}));sync();};host.onchange=sync;host.onclick=e=>{if(e.target.classList.contains('remove-workplace')){if(host.children.length===1)return toast('본점 사업장 1곳은 필요합니다.');e.target.closest('.workplace-row').remove();sync();}};sync();}
function collectWorkplaces(fd){const rows=[];for(const [key,type] of fd){if(!/^workplace_\d+_type$/.test(key))continue;const id=key.slice(0,-5),address=String(fd.get(id)||'').trim(),detail=String(fd.get(id+'Detail')||'').trim();if(!['본점','공장','연구소'].includes(type)||!address||address.length>80||detail.length>30)throw Error('사업장 종류와 주소(80자), 상세주소(30자)를 확인해 주세요.');rows.push({type,address,detail});}if(rows.length>5)throw Error('사업장은 최대 5곳까지 등록할 수 있습니다.');if(rows.filter(w=>w.type==='본점').length!==1)throw Error('본점은 정확히 1곳을 선택해 주세요. 공장과 연구소는 여러 곳 등록할 수 있습니다.');return rows;}
function bindFoundedCalendar(form){const input=form.elements.founded;input.type='text';input.placeholder='YYYY-MM-DD';input.maxLength=10;input.pattern='[0-9]{4}-[0-9]{2}-[0-9]{2}';const button=document.createElement('button');button.type='button';button.className='date-open';button.setAttribute('aria-label','설립일 달력 열기');button.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18M7 15h2M12 15h2M7 18h2"/></svg>';const wrap=document.createElement('div');wrap.className='date-control';input.before(wrap);wrap.append(input,button);button.onclick=()=>{const now=new Date(),dialog=document.createElement('dialog');dialog.className='founded-calendar';dialog.setAttribute('aria-label','설립일 선택');let selected=/^\d{4}-\d{2}-\d{2}$/.test(input.value)?new Date(input.value+'T12:00:00'):now;if(isNaN(selected))selected=now;let year=Math.min(now.getFullYear(),Math.max(1900,selected.getFullYear())),month=selected.getMonth();const value=d=>year+'-'+String(month+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');function paint(){dialog.innerHTML='<div class="calendar-title"><b>설립일 선택</b><button type="button" data-close aria-label="달력 닫기">×</button></div><div class="calendar-selects"><select aria-label="연도">'+Array.from({length:now.getFullYear()-1899},(_,i)=>now.getFullYear()-i).map(y=>'<option '+(y===year?'selected':'')+'>'+y+'</option>').join('')+'</select><select aria-label="월">'+Array.from({length:12},(_,i)=>'<option value="'+i+'" '+(i===month?'selected':'')+'>'+(i+1)+'월</option>').join('')+'</select></div><div class="calendar-days">'+['일','월','화','수','목','금','토'].map(d=>'<span>'+d+'</span>').join('')+Array.from({length:new Date(year,month,1).getDay()},()=>'<i></i>').join('')+Array.from({length:new Date(year,month+1,0).getDate()},(_,i)=>'<button type="button" data-day="'+(i+1)+'" '+(new Date(year,month,i+1)>now?'disabled':'')+' class="'+(value(i+1)===input.value?'selected':'')+'">'+(i+1)+'</button>').join('')+'</div>';dialog.querySelector('[data-close]').onclick=()=>dialog.close();const selects=dialog.querySelectorAll('select');selects[0].onchange=e=>{year=Number(e.target.value);paint();};selects[1].onchange=e=>{month=Number(e.target.value);paint();};dialog.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{input.value=value(Number(b.dataset.day));input.setCustomValidity('');dialog.close();input.dispatchEvent(new Event('input',{bubbles:true}));});}dialog.addEventListener('close',()=>{dialog.remove();button.focus();});document.body.append(dialog);paint();dialog.showModal();};input.addEventListener('input',()=>{const d=new Date(input.value+'T12:00:00');input.setCustomValidity(input.value&&(!/^\d{4}-\d{2}-\d{2}$/.test(input.value)||isNaN(d)||d>new Date())?'올바른 설립일을 입력해 주세요.':'');});}
